 return [...groups.values()].map(({sentAt,...row})=>{const loadedQty=totals.get(row.taskId)||0;return {...row,loadedQty,difference:Math.max(0,row.authorizedQty-loadedQty),issue:row.confirmed&&row.authorizedQty!==loadedQty};});
}
